export const KEY='cage-career-v1';
export const LABELS={boxing:'Boks',kickboxing:'Kickboks',wrestling:'Güreş',bjj:'Brazilian Jiu-Jitsu',stamina:'Kondisyon',strength:'Kuvvet'};
export const GYMS=[{name:'Ev',sub:'Dört duvar. Büyük hayaller.',price:0,fee:0,gain:1,wins:0},{name:'Arka Sokak Gym',sub:'Eski ekipman, sağlam temel.',price:400,fee:20,gain:1.4,wins:0},{name:'Iron District MMA',sub:'Minder, partner ve disiplin.',price:1600,fee:55,gain:1.9,wins:3},{name:'Apex Performance',sub:'Şampiyonların kampı.',price:5500,fee:130,gain:2.5,wins:7}];
export const LEAGUES=[{name:'Yer altı',min:0,purse:220,loss:75,base:13,venue:'TERK EDİLMİŞ DEPO'},{name:'Amatör lig',min:3,purse:650,loss:190,base:29,venue:'MAHALLE SPOR SALONU'},{name:'Profesyonel lig',min:7,purse:2000,loss:600,base:47,venue:'ŞEHİR ARENASI'},{name:'Dünya ligi',min:13,purse:7500,loss:1800,base:70,venue:'DÜNYA ŞAMPİYONASI'}];
export const COACHES=[{name:'Köşe yok',skill:null,price:0,fee:0,bonus:0},{name:'Cem “Solak”',skill:'boxing',price:250,fee:20,bonus:.35},{name:'Derya Hoca',skill:'bjj',price:400,fee:25,bonus:.4},{name:'Baran Demir',skill:'wrestling',price:400,fee:25,bonus:.4},{name:'Ece Yılmaz',skill:'kickboxing',price:300,fee:20,bonus:.35}];
export const MOVES=[{id:'hook',skill:'boxing',level:25,name:'Sol kroşe',type:'punch'},{id:'uppercut',skill:'boxing',level:45,name:'Aparkat',type:'punch'},{id:'combo',skill:'boxing',level:65,name:'Üçlü kombinasyon',type:'punch'},{id:'lowkick',skill:'kickboxing',level:25,name:'Low kick',type:'kick'},{id:'highkick',skill:'kickboxing',level:45,name:'High kick',type:'kick'},{id:'double',skill:'wrestling',level:25,name:'Çift bacak dalışı',type:'takedown'},{id:'control',skill:'wrestling',level:45,name:'Üst pozisyon kontrolü',type:'ground'},{id:'escape',skill:'bjj',level:25,name:'Guard kaçışı',type:'escape'},{id:'armbar',skill:'bjj',level:45,name:'Armbar',type:'submission'},{id:'triangle',skill:'bjj',level:65,name:'Üçgen boğma',type:'submission'}];
export const clamp=(x,a=0,b=100)=>Math.min(b,Math.max(a,x));
export const day=s=>Math.floor(s.hours/24)+1;
export const league=s=>LEAGUES.reduce((best,x,i)=>s.wins>=x.min?i:best,0);
export function initial(){return{version:1,name:'Çaylak',cash:250,earned:0,hours:8,energy:90,food:75,sleep:85,health:100,skills:{boxing:15,kickboxing:12,wrestling:12,bjj:12,stamina:18,strength:12},gym:0,ownedGyms:[0],coach:0,ownedCoaches:[0],wins:0,losses:0,draws:0,sessions:0,helpDay:0,moves:{},history:[],fight:null,seed:Math.floor(Math.random()*2147483646)+1};}
export function validSave(s){return s?.version===1&&typeof s.name==='string'&&s.name.length<=24&&['cash','earned','hours','wins','losses','draws','sessions','helpDay'].every(k=>Number.isFinite(s[k])&&s[k]>=0)&&['energy','food','sleep','health'].every(k=>Number.isFinite(s[k])&&s[k]>=0&&s[k]<=100)&&Object.keys(LABELS).every(k=>Number.isFinite(s.skills?.[k])&&s.skills[k]>=0&&s.skills[k]<=100)&&GYMS[s.gym]&&COACHES[s.coach]&&Array.isArray(s.ownedGyms)&&s.ownedGyms.every(i=>Number.isInteger(i)&&GYMS[i])&&Array.isArray(s.ownedCoaches)&&s.ownedCoaches.every(i=>Number.isInteger(i)&&COACHES[i])&&s.moves&&MOVES.every(m=>s.moves[m.id]===undefined||[0,1,2].includes(s.moves[m.id]))&&Array.isArray(s.history)&&s.history.length<=80&&s.history.every(h=>h&&typeof h.name==='string'&&typeof h.method==='string'&&Number.isInteger(h.day)&&h.day>0&&Number.isFinite(h.reward)&&h.reward>=0&&[0,1,2,3].includes(h.tier)&&typeof h.won==='boolean'&&typeof h.draw==='boolean')&&Number.isFinite(s.seed)&&(!s.fight||validFight(s.fight));}
const EVENT_FIELDS=['outcome','technique','phaseBefore','phaseAfter','topBefore','topAfter'];
const EVENT_OUTCOMES={idle:['rest'],guard:['rest'],punch:['hit','blocked','miss'],kick:['hit','blocked','miss'],takedown:['success','defended'],escape:['success','defended'],submission:['success','defended'],ground:['hit']};
const EVENT_TECHNIQUES=['idle','guard','direct','bodykick','takedown','ground','escape','submission',...MOVES.map(m=>m.id)];
function validAction(e){return !!(e&&typeof e.move==='string'&&Object.hasOwn(EVENT_OUTCOMES,e.move)&&EVENT_OUTCOMES[e.move].includes(e.outcome)&&[0,1].includes(e.attacker)&&EVENT_TECHNIQUES.includes(e.technique)&&['stand','ground'].includes(e.phaseBefore)&&['stand','ground'].includes(e.phaseAfter)&&[0,1].includes(e.topBefore)&&[0,1].includes(e.topAfter));}
function validEvents(f){return f.events===undefined||(Array.isArray(f.events)&&f.events.length<=60&&f.events.every((e,i)=>validAction(e)&&Number.isInteger(e.tick)&&e.tick>0&&e.tick<=f.tick&&(i===0||e.tick>f.events[i-1].tick)&&e.round===Math.floor((e.tick-1)/20)+1&&typeof e.time==='string'&&/^[0-3]:[0-5]\d$/.test(e.time)&&typeof e.text==='string'&&e.text.length<=1000));}
function validFight(f){const pair=(x,positive=false)=>Array.isArray(x)&&x.length===2&&x.every(v=>Number.isFinite(v)&&(!positive||v>0));return !!(f&&[0,1,2,3].includes(f.tier)&&pair(f.hp)&&pair(f.st)&&pair(f.score)&&pair(f.maxHp,true)&&pair(f.maxSt,true)&&['stand','ground'].includes(f.phase)&&[0,1].includes(f.top)&&f.enemy&&typeof f.enemy.name==='string'&&['boxing','kickboxing','wrestling','bjj'].includes(f.enemy.style)&&Object.keys(LABELS).every(k=>Number.isFinite(f.enemy.skills?.[k]))&&Number.isInteger(f.tick)&&f.tick>=0&&f.tick<=60&&['balanced','strike','ground','defend'].includes(f.tactic)&&typeof f.done==='boolean'&&typeof f.log==='string'&&f.last&&typeof f.last.move==='string'&&[0,1].includes(f.last.attacker)&&(EVENT_FIELDS.every(k=>f.last[k]===undefined)||validAction(f.last))&&validEvents(f)&&(!f.done||f.result&&[0,1,2].includes(f.result.winner)&&typeof f.result.method==='string'&&Number.isFinite(f.result.reward))&&(f.done||f.tick<60));}
export function rand(s){s.seed=(Math.imul(s.seed,1664525)+1013904223)>>>0;return s.seed/4294967296;}
function spend(s,n){if(s.cash<n)throw Error(`Bunun için ₺${Math.ceil(n-s.cash)} daha gerekiyor.`);s.cash-=n;}
function elapsed(s,h,e=0,f=0,sl=0){s.hours+=h;s.energy=clamp(s.energy+e);s.food=clamp(s.food+f);s.sleep=clamp(s.sleep+sl);}
function free(s){if(s.fight&&!s.fight.done)throw Error('Önce devam eden maçı tamamla.');}
export function trainingCost(s,key){return (['stamina','rope'].includes(key)?0:GYMS[s.gym].fee)+(COACHES[s.coach].skill===key?COACHES[s.coach].fee:0);}
export function train(s,key,moveId){free(s);if(!Object.hasOwn(LABELS,key)&&key!=='rope')throw Error('Geçersiz antrenman.');if(s.energy<20||s.food<20||s.sleep<15||s.health<35)throw Error('Antrenman için 20 enerji, 20 tokluk, 15 dinçlik ve 35 sağlık gerekiyor.');const m=moveId?MOVES.find(m=>m.id===moveId):null;if(moveId&&(!m||m.skill!==key||s.skills[key]<m.level||(s.moves[m.id]||0)>=2))throw Error('Bu hareket henüz çalışılamıyor.');spend(s,trainingCost(s,key));const k=key==='rope'?'stamina':key;const readiness=.7+(s.food+s.sleep)/500;const bonus=COACHES[s.coach].skill===k?COACHES[s.coach].bonus:0;const gain=(k==='strength'?4.4:3.5)*(['stamina','rope'].includes(key)?1:GYMS[s.gym].gain)*(1+bonus)*(1-s.skills[k]/145)*readiness;s.skills[k]=clamp(s.skills[k]+gain);elapsed(s,1,-18,-11,-9);s.sessions++;if(m){s.moves[m.id]=(s.moves[m.id]||0)+1;return s.moves[m.id]===2?`${m.name} öğrenildi! Maçta kullanılabilir.`:`${m.name}: 1/2 çalışma tamamlandı.`}return `${LABELS[k]} +${gain.toFixed(1)} · İyi bir seans.`;}
export function recover(s,action){free(s);switch(action){case 'meal':spend(s,35);elapsed(s,.5,5,45,-1);return 'Sıcak yemek: +45 tokluk, +5 enerji.';case 'protein':spend(s,80);elapsed(s,.5,12,70,-1);s.health=clamp(s.health+8);return 'Dengeli öğün: +70 tokluk, +8 sağlık.';case 'sleep':elapsed(s,8,75,-14,90);s.health=clamp(s.health+32);return '8 saat uyudun. Yeni bir başlangıç.';case 'rest':elapsed(s,2,30,-5,8);s.health=clamp(s.health+14);return 'Toparlandın: +30 enerji, +14 sağlık.';case 'help':if(s.helpDay===day(s))throw Error('Bugünkü ücretsiz yemeğini aldın. Yarın yeniden uğra.');s.helpDay=day(s);s.food=clamp(s.food+55);return 'Mahalle mutfağı: +55 tokluk. Birlikte ayağa kalkarız.';case 'job':if(s.energy<15||s.food<10)throw Error('Çalışmak için 15 enerji ve 10 tokluk gerekiyor. Önce dinlen veya ücretsiz yemek al.');elapsed(s,3,-15,-10,-15);s.cash+=110;s.earned+=110;return 'Gündelik işi bitirdin. +₺110';default:throw Error('Geçersiz eylem.');}}
export function chooseGym(s,i){free(s);const g=GYMS[i];if(!g)throw Error('Geçersiz salon.');if(s.wins<g.wins)throw Error(`Bu salon için ${g.wins} galibiyet gerekiyor.`);if(!s.ownedGyms.includes(i)){spend(s,g.price);s.ownedGyms.push(i)}s.gym=i;return `${g.name} artık antrenman alanın.`;}
export function chooseCoach(s,i){free(s);const c=COACHES[i];if(!c)throw Error('Geçersiz antrenör.');if(!s.ownedCoaches.includes(i)){spend(s,c.price);s.ownedCoaches.push(i)}s.coach=i;return i?`${c.name} köşene katıldı.`:'Kendi programına döndün.';}
export function opponent(s,tier=league(s)){const styles=['boxing','wrestling','kickboxing','bjj'];const i=(s.wins+s.losses+s.draws)%8;const names=['Bora “Çekiç”','Mert Kaya','Aras “Bozkurt”','Deniz Akın','Kaan “Fırtına”','Eren Keskin','Leo Silva','Alex Volkov'];const style=styles[i%4];const skills={};for(const k of Object.keys(LABELS))skills[k]=clamp(LEAGUES[tier].base+(i%3)*2+(k===style?7:0));return{name:names[i],style,skills};}
export function startFight(s,tier=league(s)){free(s);if(!Number.isInteger(tier)||tier<0||tier>league(s))throw Error('Bu lig henüz açık değil.');if(s.energy<35||s.food<25||s.sleep<25||s.health<50)throw Error('Maç için en az 35 enerji, 25 tokluk, 25 dinçlik ve 50 sağlık gerekiyor.');const enemy=opponent(s,tier);const maxHp=[110+s.skills.strength*.5,110+enemy.skills.strength*.5];const maxSt=[80+s.skills.stamina*.8,80+enemy.skills.stamina*.8];s.fight={tier,enemy,hp:[maxHp[0]*(.65+s.health*.0035),maxHp[1]],maxHp,st:[maxSt[0]*(.65+(s.energy+s.sleep)/570),maxSt[1]],maxSt,score:[0,0],tick:0,phase:'stand',top:0,tactic:'balanced',done:false,result:null,log:'Zil çaldı. Gardını al!',last:{move:'idle',attacker:0,outcome:'rest',technique:'idle',phaseBefore:'stand',phaseAfter:'stand',topBefore:0,topAfter:0},events:[],id:s.hours+'-'+s.seed};elapsed(s,1,-30,-18,-17);return s.fight;}
export function tactic(s,t){if(!s.fight||s.fight.done)throw Error('Aktif maç yok.');if(!['balanced','strike','ground','defend'].includes(t))throw Error('Geçersiz taktik.');s.fight.tactic=t;}
export function stepFight(s){const f=s.fight;if(!f||f.done)return f;const phaseBefore=f.phase,topBefore=f.top;f.tick++;const a=f.tick%2,b=1-a,as=a===0?s.skills:f.enemy.skills,bs=b===0?s.skills:f.enemy.skills;const at=a===0?f.tactic:f.enemy.style==='wrestling'||f.enemy.style==='bjj'?'ground':'strike';const bt=b===0?f.tactic:'balanced';const who=a===0?s.name:f.enemy.name;let move='punch',outcome='blocked',technique='direct';const tired=.45+.55*clamp(f.st[a]/f.maxSt[a],0,1);let msg='';const known=type=>a===0?MOVES.filter(m=>m.type===type&&s.moves[m.id]>=2):[];
 f.st[a]=clamp(f.st[a]+as.stamina*.025,0,f.maxSt[a]);f.st[b]=clamp(f.st[b]+2+bs.stamina*.025,0,f.maxSt[b]);
 if(at==='defend'&&rand(s)<.48){f.st[a]=clamp(f.st[a]+13,0,f.maxSt[a]);msg=`${who} mesafeyi koruyor, nefes topluyor.`;move='guard';outcome='rest';technique='guard';}
 else if(f.phase==='stand'&&rand(s)<(at==='ground'?.62:.08)){move='takedown';technique=known('takedown')[0]?.id||'takedown';outcome='defended';f.st[a]=Math.max(0,f.st[a]-10);if(rand(s)<clamp(.48+(as.wrestling-bs.wrestling)/125+(as.strength-bs.strength)/500+(known('takedown').length?.09:0),.12,.88)*tired){f.phase='ground';f.top=a;f.score[a]+=7;outcome='success';msg=`${who}, ${known('takedown').length?'çift bacak dalışıyla':'bir dalışla'} rakibini yere aldı.`}else msg=`${who} yere indirmeyi denedi, rakibi savundu.`;}
 else if(f.phase==='ground'){const escapeBonus=known('escape').length?.12:0;if(at==='strike'||at==='defend'){move='escape';technique='escape';outcome='defended';if(rand(s)<clamp(.23+(as.bjj-bs.wrestling)/130+escapeBonus,.1,.8)){f.phase='stand';outcome='success';msg=`${who} ${escapeBonus?'guard kaçışıyla':'alan açarak'} ayağa kalktı.`}else msg=`${who} yerden çıkmak için mücadele ediyor.`;f.st[a]=Math.max(0,f.st[a]-5)}else if(rand(s)<.24){const subs=known('submission');const sub=subs.length?subs[Math.floor(rand(s)*subs.length)]:null;move='submission';technique=sub?.id||'submission';outcome='defended';const chance=clamp(.04+(as.bjj-bs.bjj)/280+(sub?.id==='triangle'?.1:sub?.id==='armbar'?.07:0)+(f.st[b]<20?.08:0),.015,.35)*tired;f.st[a]=Math.max(0,f.st[a]-8);if(rand(s)<chance){outcome='success';msg=`${who}, ${sub?.name||'pes ettirme'} ile maçı bitirdi!`;finishFight(s,a,'Submission');}else msg=`${who} ${sub?.name||'pes ettirme'} arıyor; rakibi savunuyor.`;}else{move='ground';technique=known('ground')[0]?.id||'ground';outcome='hit';const damage=(4+as.bjj*.055+as.wrestling*.035+as.strength*.035)*tired*(f.top===a?1.2:.7)*(known('ground').length?1.2:1);f.hp[b]-=damage;f.score[a]+=damage;f.st[a]=Math.max(0,f.st[a]-5);msg=`${who} yerde ${f.top===a?'üst pozisyondan baskı kuruyor':'pozisyon kazanıyor'}.`;if(rand(s)<clamp(.15+(as.bjj-bs.bjj)/200+(known('ground').length?.1:0),.04,.5)){f.top=a;msg=`${who} yerde pozisyonu çevirdi!`}}}
 else{const kick=rand(s)<(as.kickboxing/(as.kickboxing+as.boxing))*.7;move=kick?'kick':'punch';const skill=kick?'kickboxing':'boxing';const moves=known(move);const unlocked=moves.length&&rand(s)<.5?moves[Math.floor(rand(s)*moves.length)]:null;technique=unlocked?.id||(kick?'bodykick':'direct');const accuracy=clamp(.62+(as[skill]-bs[skill])/155-(bt==='defend'?.14:0),.17,.9)*(.7+.3*tired);f.st[a]=Math.max(0,f.st[a]-(kick?8:6)*(at==='strike'?1.2:1));if(rand(s)<accuracy){outcome='hit';const damage=(6+as.strength*.1+as[skill]*.055)*tired*(at==='strike'?1.15:1)*(unlocked?1.25:1)*(bt==='defend'?.75:1);f.hp[b]-=damage;f.score[a]+=damage;msg=`${who}: ${unlocked?.name||(kick?'gövdeye tekme':'direkt yumruk')} isabetli!`}else msg=`${who}: ${kick?'tekmesi':'yumruğu'} gardda kaldı.`;}
 // Preserve the action's ending pose before a round break resets the fighters.
 f.last={move,attacker:a,outcome,technique,phaseBefore,phaseAfter:f.phase,topBefore,topAfter:f.top};f.log=msg;
 if(!f.done&&f.hp[b]<=0)finishFight(s,a,'TKO');if(!f.done&&f.tick>=60){const d=f.score[0]-f.score[1];finishFight(s,Math.abs(d)<3?2:d>0?0:1,'Hakem kararı')}else if(!f.done&&f.tick%20===0){f.phase='stand';f.st=f.st.map((v,i)=>clamp(v+f.maxSt[i]*.22,0,f.maxSt[i]));f.log+=' Raund bitti; köşede toparlanıyorsunuz.'}
 if(f.done)f.log+=` Maç bitti: ${f.result.method} · ${f.result.winner===2?'Berabere':(f.result.winner===0?s.name:f.enemy.name)+' kazandı'}.`;
 const remaining=180-(((f.tick-1)%20)+1)*9;
 f.events=[...(f.events||[]),{tick:f.tick,round:Math.floor((f.tick-1)/20)+1,time:Math.floor(remaining/60)+':'+String(remaining%60).padStart(2,'0'),text:f.log,...f.last}].slice(-60);
 return f;
}
function finishFight(s,winner,method){const f=s.fight;if(f.done)return;const old=league(s);f.done=true;const won=winner===0,draw=winner===2;const reward=draw?Math.round(LEAGUES[f.tier].purse*.6):won?LEAGUES[f.tier].purse:LEAGUES[f.tier].loss;if(won)s.wins++;else if(draw)s.draws++;else s.losses++;s.cash+=reward;s.earned+=reward;s.health=clamp(35+Math.max(0,f.hp[0])/f.maxHp[0]*60,25,95);s.energy=clamp(s.energy-8);f.result={winner,method,reward,promotion:league(s)>old,champion:s.wins>=20&&f.tier===3&&won};s.history.unshift({name:f.enemy.name,won,draw,method,reward,day:day(s),tier:f.tier});s.history=s.history.slice(0,80);}
